import json
d=json.load(open('dnd.json'))
def walk(n,out):
    if isinstance(n,dict):
        if n.get('type')=='text': out.append(n.get('text',''))
        elif n.get('type')=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif n.get('type')=='reference': out.append(n.get('title') or '')
        elif n.get('type')=='heading': out.append('\n## '+ (n.get('text','')) + '\n')
        elif n.get('type')=='paragraph':
            for c in n.get('inlineContent',[]): walk(c,out)
            out.append('\n')
        elif n.get('type')=='listItem':
            out.append('- ')
            for c in n.get('content',[]): walk(c,out)
        else:
            for k in ('content','inlineContent','items','sections','primaryContentSections','anchor'):
                if k in n:
                    for c in (n[k] if isinstance(n[k],list) else [n[k]]): walk(c,out)
    elif isinstance(n,list):
        for c in n: walk(c,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
print(''.join(out))
print('=== METADATA ===')
print(json.dumps(d.get('metadata',{}),indent=1)[:1500])
